#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
const int MOD1=998244353,MOD2=1e9+7;
const int MAXN=2e6,MAX=1e6;
ll n,c;
int total,answer,limit,power[MAXN],sumArr[MAXN];
vector<int> vec[MAXN];

inline int subtract(int x,int y,int m){return (x-y<0)?x-y+m:x-y;}
inline int addMod(int x,int y,int m){return (x+y>=m)?x+y-m:x+y;}
inline void dfs(int position,int current){
	if(current<=n){
		++total;int x=subtract(total,current,MOD1);
		vec[position-1].push_back(x);sumArr[position-1]=addMod(sumArr[position-1],x,MOD2);
	}
	if(position>6) return ;
	for(int i=0;i<=9;++i) dfs(position+1,current*10+i);
}
inline void process(int position,ll current){
	if(current>n) return ;
	if(position>1){
		if(10ll*current*MAX>n&&1ll*(current+1)*MAX-1<=n){
			for(int i=0;i<7;++i){
				int x=((c-1ll*current*power[i])%MOD1+MOD1)%MOD1;
				int p=lower_bound(vec[i].begin(),vec[i].end(),MOD1-x)-vec[i].begin();
				answer=addMod(answer,addMod(1ll*x*vec[i].size()%MOD2,sumArr[i],MOD2),MOD2);
				answer=subtract(answer,1ll*MOD1*(vec[i].size()-p)%MOD2,MOD2);
			}
			c+=total;
			return ;
		}
		++c;answer=addMod(answer,((c-current)%MOD1+MOD1)%MOD1,MOD2);
	}
	for(int i=(position==1?1:0);i<=9;++i) process(position+1,current*10+i);
}
int main(){
	scanf("%lld",&n);
	power[0]=1;for(int i=1;i<9;++i) power[i]=10*power[i-1];
	dfs(1,0);
	for(int i=0;i<7;++i)
		sort(vec[i].begin(),vec[i].end()); 
	process(1,0);
	printf("%d\n",answer);
	return 0;
}
